    @Test
    void noticeExactlyAtCutoffIsInvalidAndDeemedAccepted() {
        setupLc("LC-ATCUTOFF", "1000.00");
        lcService.present(presentRequest("r-present-at", "LC-ATCUTOFF", "P-ATCUTOFF", null));

